begin;
insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data,aud,role,encrypted_password,email_confirmed_at,created_at,updated_at) select ('fb510000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid,'synthetic-gpu-diagnostic-'||x||'@fixture.invalid',jsonb_build_object('full_name','GPU diagnostic fixture','account_type_request','EXTERNAL'),'{}','authenticated','authenticated','fixture-no-password',now(),now(),now() from generate_series(1,2)x;
