insert into cbgpu_schools.memberships(user_id,school_id,membership_type,status,verified,school_roles)values('fb510000-0000-4000-8000-000000000001','fixture-diagnostic-b','TEACHER','ACTIVE',true,array['GPU_ADMIN']),('fb510000-0000-4000-8000-000000000002','cbsh','TEACHER','ACTIVE',true,array['GPU_ADMIN']);
insert into cbgpu_schools.gpu_nodes(id,school_id,name,status,sharing_enabled,public_key,credential_version)values('fb530000-0000-4000-8000-000000000001','fixture-diagnostic-b','Synthetic diagnostic node','OFFLINE',false,repeat('a',64),1);
select set_config('request.jwt.claims','{"sub":"fb510000-0000-4000-8000-000000000002","role":"authenticated","session_id":"fb520000-0000-4000-8000-000000000002"}',true);set local role authenticated;
do $$begin begin perform public.school_gpu_diagnostic_admin('fixture-diagnostic-b','create','{"node_id":"fb530000-0000-4000-8000-000000000001","idempotency_key":"fb540000-0000-4000-8000-000000000001"}');raise exception 'CROSS_SCHOOL_DIAGNOSTIC';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claims','{"sub":"fb510000-0000-4000-8000-000000000001","role":"authenticated","session_id":"fb520000-0000-4000-8000-000000000001"}',true);
select public.school_gpu_diagnostic_admin('fixture-diagnostic-b','create','{"node_id":"fb530000-0000-4000-8000-000000000001","idempotency_key":"fb540000-0000-4000-8000-000000000001"}');
do $$declare x jsonb;begin x:=public.school_gpu_diagnostic_admin('fixture-diagnostic-b','create','{"node_id":"fb530000-0000-4000-8000-000000000001","idempotency_key":"fb540000-0000-4000-8000-000000000001"}');if x->>'duplicate'<>'true' or x#>>'{command,execution_ready}'<>'false' then raise exception 'DIAGNOSTIC_IDEMPOTENCY';end if;begin perform count(*)from cbgpu_schools.gpu_diagnostic_commands;raise exception 'COMMAND_QUEUE_EXPOSED';exception when insufficient_privilege then null;end;end$$;
reset role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
create temp table diagnostic_lease as select public.school_gpu_diagnostic_device('fb530000-0000-4000-8000-000000000001',1,1,extract(epoch from clock_timestamp())::bigint,'claim','{"action":"claim","agent_protocol":2}')value;
do $$begin begin perform public.school_gpu_diagnostic_device('fb530000-0000-4000-8000-000000000001',1,1,extract(epoch from clock_timestamp())::bigint,'claim','{"action":"claim","agent_protocol":2}');raise exception 'COMMAND_REPLAY';exception when insufficient_privilege then null;end;end$$;
do $$begin begin perform public.school_gpu_diagnostic_device('fb530000-0000-4000-8000-000000000001',2,2,extract(epoch from clock_timestamp())::bigint,'claim','{"action":"claim","agent_protocol":2}');raise exception 'CREDENTIAL_VERSION_BYPASS';exception when insufficient_privilege then null;end;end$$;
select public.school_gpu_diagnostic_device('fb530000-0000-4000-8000-000000000001',1,2,extract(epoch from clock_timestamp())::bigint,'renew',(select (value->'command')-'expires_at'-'kind'-'payload'||'{"action":"renew"}'::jsonb from diagnostic_lease));
do $$declare x jsonb;begin x:=public.school_gpu_diagnostic_device('fb530000-0000-4000-8000-000000000001',1,3,extract(epoch from clock_timestamp())::bigint,'result',(select(value->'command')-'expires_at'-'kind'-'payload'||'{"action":"result","result":{"status":"SUCCEEDED","gpus":[{"index":0,"hardware_uuid":"GPU-aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa","name":"Synthetic NVIDIA fixture","memory_total_mib":100,"memory_used_mib":0,"utilization_percent":0}],"error_code":null}}'::jsonb from diagnostic_lease));if x->>'accepted'<>'true' then raise exception 'DIAGNOSTIC_RESULT_NOT_ACCEPTED';end if;end$$;
do $$declare x jsonb;begin x:=public.school_gpu_diagnostic_device('fb530000-0000-4000-8000-000000000001',1,4,extract(epoch from clock_timestamp())::bigint,'result',(select(value->'command')-'expires_at'-'kind'-'payload'||'{"action":"result","result":{"status":"SUCCEEDED","gpus":[{"index":0,"hardware_uuid":"GPU-aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa","name":"Synthetic NVIDIA fixture","memory_total_mib":100,"memory_used_mib":0,"utilization_percent":0}],"error_code":null}}'::jsonb from diagnostic_lease));if x->>'duplicate'<>'true'then raise exception 'LOST_ACK_RETRY_NOT_IDEMPOTENT';end if;end$$;
