insert into diagnostic_lease select public.school_gpu_diagnostic_device('fb530000-0000-4000-8000-000000000001',1,5,extract(epoch from clock_timestamp())::bigint,'claim','{"action":"claim","agent_protocol":2}');
update cbgpu_schools.gpu_diagnostic_commands set lease_until=clock_timestamp()-interval '1 second' where id=(select(value#>>'{command,command_id}')::uuid from diagnostic_lease);
do $$begin begin perform public.school_gpu_diagnostic_device('fb530000-0000-4000-8000-000000000001',1,6,extract(epoch from clock_timestamp())::bigint,'renew',(select(value->'command')-'expires_at'-'kind'-'payload'||'{"action":"renew"}'::jsonb from diagnostic_lease));raise exception 'EXPIRED_LEASE_RENEW';exception when insufficient_privilege then null;end;end$$;
do $$declare x jsonb;begin x:=public.school_gpu_diagnostic_device('fb530000-0000-4000-8000-000000000001',1,6,extract(epoch from clock_timestamp())::bigint,'claim','{"action":"claim","agent_protocol":2}');if x#>>'{command,lease_epoch}'<>'2'then raise exception 'LEASE_EPOCH_NOT_ADVANCED';end if;end$$;
delete from auth.sessions where id='fb520000-0000-4000-8000-000000000001';
do $$declare x jsonb;begin x:=public.school_gpu_diagnostic_device('fb530000-0000-4000-8000-000000000001',1,7,extract(epoch from clock_timestamp())::bigint,'claim','{"action":"claim","agent_protocol":2}');if x->'command'<>'null'::jsonb then raise exception 'REVOKED_REQUESTER_COMMAND';end if;end$$;
update cbgpu_schools.gpu_nodes set status='REVOKED',credential_version=2 where id='fb530000-0000-4000-8000-000000000001';
